SELECT ?cat (SAMPLE(?pname) AS ?publisher) (COUNT(DISTINCT ?ds) AS ?n) WHERE {
  VALUES ?cat { <http://data.europa.eu/88u/catalogue/oppnadata> <http://data.europa.eu/88u/catalogue/geodata-se> }
  ?cat dcat:dataset ?ds .
  ?ds dct:publisher ?p . ?p foaf:name ?pname .
  FILTER(CONTAINS(LCASE(STR(?pname)), "göteborg") || CONTAINS(LCASE(STR(?pname)), "goteborg") || CONTAINS(LCASE(STR(?pname)), "gothenburg") || CONTAINS(LCASE(STR(?pname)), "västra götaland") || CONTAINS(LCASE(STR(?pname)), "chalmers") || CONTAINS(LCASE(STR(?pname)), "västtrafik"))
} GROUP BY ?cat ?p ORDER BY DESC(?n) LIMIT 60

