PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?ds (SAMPLE(?t) AS ?title) WHERE {
  ?ds dct:publisher <http://dataportal.se/organisation/SE2120001355> ; dct:title ?t .
  FILTER(LANG(?t) = "sv" || LANG(?t) = "")
} GROUP BY ?ds

PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?ds (SAMPLE(?d) AS ?desc) (SAMPLE(?mod) AS ?modified) WHERE {
  ?ds dct:publisher <http://dataportal.se/organisation/SE2120001355> ; dct:description ?d .
  FILTER(LANG(?d) = "sv" || LANG(?d) = "")
  OPTIONAL { ?ds dct:modified ?mod }
} GROUP BY ?ds

