PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?pub (SAMPLE(?lbl) AS ?nombre) (COUNT(DISTINCT ?ds) AS ?n) WHERE {
