  FILTER(REGEX(?t, "paro registrado|demandantes de empleo|afiliaci[oó]n|afiliados|contratos registrados|contrataci[oó]n laboral|mercado de trabajo|mercado laboral|poblaci[oó]n activa|encuesta de poblaci|desempleo|parados|ofertas de empleo|empresas de trabajo temporal|tasa de paro|ocupados", "i"))
} GROUP BY ?pub ORDER BY DESC(?n)

