} ORDER BY ?pub ?t

PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?t ?freq (GROUP_CONCAT(DISTINCT ?fmt; separator=", ") AS ?formatos) (SAMPLE(?url) AS ?descarga) WHERE {
  VALUES ?ds { <https://datos.gob.es/catalogo/e05072501-parados_por_sector_economico_y_sexo> <https://datos.gob.es/catalogo/e05072501-beneficiarios_prestacion_desempleo> <https://datos.gob.es/catalogo/e05072501-afiliados-de-la-seguridad-social-al-ultimo-dia-del-mes-por-sexo-provincia-y-regimen> <https://datos.gob.es/catalogo/e05072501-afiliados-rg-al-ultimo-dia-del-mes-por-tipo-contrato-jornada-actividad-cnae-25-y-sexo> }
  ?ds dct:title ?t .
  OPTIONAL { ?ds dct:accrualPeriodicity ?freq }
  OPTIONAL { ?ds dcat:distribution ?d . OPTIONAL { ?d dct:format ?f . ?f ?p ?fmt . FILTER(isLiteral(?fmt)) } OPTIONAL { ?d dcat:accessURL ?url } }
  FILTER(lang(?t)="es")
} GROUP BY ?t ?freq
